"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8071],{59078:e=>{e.exports=JSON.parse('{"functions":[{"name":"watch","desc":"Calls `onAttach(model, cleaner)` once per placed Model named `placeableName`\\n(existing and future). `cleaner` is destroyed when the Model leaves\\n`workspace.PlacedObjects`. `onAttach` may spawn its own thread to wait on\\nstreaming parts; check that `cleaner` is still the live one afterwards.","params":[{"name":"placeableName","desc":"","lua_type":"string"},{"name":"onAttach","desc":"","lua_type":"(model: Model, cleaner: Janitor.Janitor) -> ()"}],"returns":[],"function_type":"static","source":{"line":26,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/Discovery.luau"}}],"properties":[],"types":[],"name":"Discovery","desc":"Finds every placed turret of one kind. `watch` follows `workspace.PlacedObjects`\\nfor Models whose `PlaceableName` matches, hands each one to the caller with a\\nfresh `Janitor`, and destroys that Janitor when the Model leaves PlacedObjects\\n(removed or stashed). A Model that arrives without the attribute is picked up\\nwhen `PlacementServer` sets it, right after parenting.","realm":["Client"],"source":{"line":12,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/Discovery.luau"}}')}}]);